def transform(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    # find horizontal bars: rows with a colored run
    bars=[]  # (row, color, span_start, span_end)
    for r in range(H):
        row=g[r]
        if any(c!=0 for c in row):
            cols=[c for c in range(W) if row[c]!=0]
            # assume single color per bar
            cols_set={row[c] for c in cols}
            if len(cols_set)==1 and max(cols)-min(cols)+1>2:
                bars.append((r, row[cols[0]], min(cols), max(cols)))
    # vertical lines: columns with vertical colored cells below all bars
    for c in range(W):
        col=[g[r][c] for r in range(H)]
        nz=[r for r in range(H) if col[r]!=0]
        if not nz: continue
        if any(r in [b[0] for b in bars] for r in nz): continue
        lc=col[nz[-1]]
        covering=[b for b in bars if b[2]<=c<=b[3]]
        for r in range(H):
            below=[b for b in covering if b[0]>=r]
            if below:
                out[r][c]=min(below,key=lambda b:b[0])[1]
            else:
                out[r][c]=lc
    # fill bar gaps within span
    for r,colr,s,e in bars:
        for c in range(s,e+1):
            out[r][c]=colr
    return out
