        covering=[b for b in bars if b[2]<=c<=b[3]]
        for r in range(H):
            below=[b for b in covering if b[0]>=r]
            out[r][c]=min(below,key=lambda b:b[0])[1] if below else lc
    for r,colr,s,e in bars:
        for c,_ in lines:
